"""Parser for vla-smolvla-realtime-chunking.

The metrics are accepted ONLY from inside the last `MLSB_RESULT_BEGIN <nonce>` ...
`MLSB_RESULT_END <nonce>` block, which scripts/run.sh prints after the evaluated
process has exited, with a nonce the policy process never sees. A `TEST_METRICS`
line printed from inside the policy process -- before a crash or not -- therefore
never counts, and a run that failed yields no metric at all.
"""

import math
import re
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent.parent
# Only reach for the repo checkout when mlsbench is genuinely absent. Under Harbor
# this parser is exec'd from /tmp/mlsbench-verifier.XXXXXX/meta/, so a
# __file__-derived root would put an agent-writable directory on sys.path.
try:  # noqa: E402
    import mlsbench  # noqa: F401
except ModuleNotFoundError:  # pragma: no cover - native checkout, no install
    sys.path.insert(0, str(PROJECT_ROOT / "src"))

from mlsbench.agent.parsers import OutputParser, ParseResult

_BEGIN = re.compile(r"^\s*MLSB_RESULT_BEGIN\s+([0-9a-f]{16,})\s*$")
_END = re.compile(r"^\s*MLSB_RESULT_END\s+([0-9a-f]{16,})\s*$")
_METRIC = re.compile(r"^\s*TEST_METRICS\s+(.*\S)\s*$")
_KV = re.compile(r"([a-z_]+)=([-+0-9.eEna]+)")


def trusted_metrics(raw_output: str) -> dict[str, float] | None:
    lines = raw_output.splitlines()
    end_idx, nonce = None, None
    for i in range(len(lines) - 1, -1, -1):
        m = _END.match(lines[i])
        if m:
            end_idx, nonce = i, m.group(1)
            break
    if end_idx is None:
        return None
    begin_idx = None
    for i in range(end_idx - 1, -1, -1):
        m = _BEGIN.match(lines[i])
        if m and m.group(1) == nonce:
            begin_idx = i
            break
    if begin_idx is None:
        return None
    found = None
    for line in lines[begin_idx + 1 : end_idx]:
        m = _METRIC.match(line)
        if m:
            found = {k: float(v) for k, v in _KV.findall(m.group(1))}
    if not found or "success_rate" not in found or not (0.0 <= found["success_rate"] <= 1.0):
        return None
    return found


class Parser(OutputParser):
    def parse(self, cmd_label: str, raw_output: str) -> ParseResult:
        feedback_parts: list[str] = []
        metrics: dict[str, float] = {}
        suffix = cmd_label.replace("-", "_")

        for prefix in ("SETTINGS ", "POLICY_LOADED ", "FINAL "):
            hits = [l.strip() for l in raw_output.splitlines() if l.strip().startswith(prefix)]
            if hits:
                feedback_parts.append(hits[-1])

        found = trusted_metrics(raw_output)
        if found is not None:
            metrics[f"success_rate_{suffix}"] = found["success_rate"]
            for k in ("max_accel", "boundary_jump"):
                v = found.get(k)
                if v is not None and math.isfinite(v):
                    metrics[f"{k}_{suffix}"] = v
            feedback_parts.append(f"{cmd_label}: " + " ".join(f"{k}={v:.4f}" for k, v in found.items()))
        else:
            invalid = [l.strip() for l in raw_output.splitlines() if l.strip().startswith("TEST_METRICS_INVALID")]
            if invalid:
                feedback_parts.append(invalid[-1])
            else:
                feedback_parts.append(f"{cmd_label}: no trusted result block found")

        per_task = [l.strip() for l in raw_output.splitlines() if l.strip().startswith("TASK_METRICS ")]
        if per_task:
            feedback_parts.append("Per-task:\n" + "\n".join(per_task[-10:]))
        errors = [l.rstrip() for l in raw_output.splitlines() if "Traceback" in l or "Error" in l]
        if errors and not metrics:
            feedback_parts.append("Errors:\n" + "\n".join(errors[-8:]))
        return ParseResult(feedback="\n".join(feedback_parts), metrics=metrics)
